/* SHOPPER 12 — personal-first, local-first. All displayed source data is qualified. */
'use strict';
const $=s=>document.querySelector(s);
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>(Number(n||0)/100).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
const dateStr=x=>x?new Date(x).toLocaleDateString('es-ES',{day:'2-digit',month:'short',year:'numeric'}):'—';
const placeLabel=p=>p?.name||'Madrid · Sin lugar';
let timer=null,map=null,searchTimer=null;
const S={user:null,csrf:'',config:null,boot:null,observedPrices:[],view:'home',placeId:null,coords:{lat:40.4168,lon:-3.7038},locationGranted:false,stores:[],catalog:[],chain:'',term:'',basketId:null,basket:null,feed:[],offers:[],purchases:[],settings:{auto_pantry:false},activeTab:'stores',radius:6,storeQ:'',storeChain:'',pendingProduct:null};
function toast(s,err=false){const el=$('#toast');el.textContent=s;el.className=err?'show error':'show';clearTimeout(timer);timer=setTimeout(()=>el.className='',4100)}
function fetchOpts(method,body){let h={'Accept':'application/json'};if(body!==undefined)h['Content-Type']='application/json';if(S.csrf&&method!=='GET')h['X-Shopper-CSRF']=S.csrf;return{method,headers:h,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)}}
async function api(url,method='GET',body){let r=await fetch(url,fetchOpts(method,body));let d;try{d=await r.json()}catch{d={detail:'Respuesta inesperada del servidor'}}if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail||'Error desconocido'));return d}
const authRequired=()=>{if(S.user)return false;authModal('register');return true};
const currentPlace=()=>S.boot?.places?.find(p=>p.id===S.placeId);
const placeStores=pid=>(S.boot?.network||[]).filter(x=>x.place_id===Number(pid)).map(x=>x.store_id);
const myBaskets=()=>(S.boot?.baskets||[]);
const editableBasket=()=>myBaskets().find(b=>b.kind==='actual'&&b.my_role==='owner') || myBaskets().find(b=>b.my_role!=='reader');
const shopEmoji=cat=>({Arroz:'🍚',Leche:'🥛',Huevos:'🥚',Aceite:'🫒',Fruta:'🍎',Bebidas:'🥤',Despensa:'🥫',Limpieza:'🧼',Pan:'🥖'}[cat]||'🛒');
function modal(body){$('#dialogBody').innerHTML=body;$('#modalBack').classList.remove('hidden');$('#dialogBody input:not([type=hidden]),#dialogBody select')?.focus()}
function closeModal(){$('#modalBack').classList.add('hidden');$('#dialogBody').innerHTML=''}
function headline(label,title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">${E(label)}</div><div class="h1">${E(title)}</div><div class="desc">${subtitle}</div></div>${action}</div>`}
function empty(icon,title,desc='',action=''){return `<div class="empty"><span>${icon}</span><strong>${E(title)}</strong><p class="desc">${desc}</p>${action}</div>`}
function tiles(baskets){return `<div class="grid cols4">${baskets.map(b=>`<article class="collection" data-open-basket="${b.id}" tabindex="0" role="button" aria-label="Abrir cesta ${E(b.title)}"><div class="cover ${E(b.accent||'sage')}">${E(b.cover_emoji||'🧺')}<small>${E(b.kind||'ocasional')}</small></div><div class="collection-body"><h3>${E(b.title)}</h3><p>${b.item_count||0} productos · ${E(S.boot?.places?.find(p=>p.id===b.place_id)?.name||'Todos los lugares')}</p><div class="tiny-tags"><span>${b.my_role==='owner'?'Tu cesta':'Compartida'}</span><span>${b.kind==='evento'?dateStr(b.event_on):'Reutilizable'}</span></div></div></article>`).join('')}</div>`}
function storeBadge(s){let c=String(s.chain||'').toLowerCase();return `<div class="store-brand ${c.includes('dia')?'dia':c.includes('carrefour')?'carrefour':c.includes('lidl')?'lidl':c.includes('mercadona')?'mercadona':''}">${E((s.chain||'?').substring(0,3).toUpperCase())}</div>`}
function storeCard(s){let saved=!!(S.placeId&&placeStores(S.placeId).includes(s.id));return `<article class="store-row">${storeBadge(s)}<div class="store-copy"><strong>${E(s.name)}</strong><small>${E(s.address||'Dirección incompleta')}</small><small>${E(s.source_type||'fuente no indicada')} · ${s.distance_km==null?'Ubicación sin confirmar':s.distance_km+' km'}</small></div><div class="store-actions">${s.distance_km!=null?`<span class="store-dist">${s.distance_km} km</span>`:''}${S.user&&S.placeId?`<button class="btn small ${saved?'ghost':'primary'}" data-action="networkToggle" data-id="${s.id}" data-save="${saved?'0':'1'}">${saved?'✓ En mi red':'+ Guardar'}</button>`:''}</div></article>`}
function productsCards(items){return `<div class="product-grid">${items.map(p=>`<article class="product"><div class="product-pic">${shopEmoji(p.category)}<small>${E(p.chain||'Producto')}</small></div><div class="product-body"><p>${E(p.brand||p.category||'')}</p><h3>${E(p.name)}</h3><p>${E(p.format||'')}</p><div class="price-date">Precio web publicado ${E(p.observed_on||S.catalogDate||'· muestra fechada')} · no stock local</div><div class="product-bottom"><div><strong>${p.price_cents!=null?euro(p.price_cents):'—'}</strong><small>no confirmado en tienda</small></div><button class="btn primary small" data-action="addProduct" data-id="${p.product_id||0}" aria-label="Añadir ${E(p.name)}">＋</button></div>${p.source_url?`<a class="mini" href="${E(p.source_url)}" target="_blank" rel="noopener noreferrer">Ver fuente ↗</a>`:''}</div></article>`).join('')}</div>`}
function nav(view){S.view=view;S.activeTab=S.activeTab||'stores';document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));render();}
async function refresh(){if(!S.user)return;S.boot=await api('/api/bootstrap');if(S.placeId&&!S.boot.places.some(p=>p.id===S.placeId))S.placeId=null;await readBasket();render()}
async function readBasket(){if(!S.user)return;let b=myBaskets().find(b=>b.id===S.basketId)||editableBasket();if(!b){S.basket=null;S.basketId=null;return}S.basketId=b.id;S.basket=await api(`/api/baskets/${b.id}`)}
async function loadStores(){try{
 const qs=`lat=${encodeURIComponent(S.coords.lat)}&lon=${encodeURIComponent(S.coords.lon)}&radius_km=${S.radius}`;
 const [stores,prices]=await Promise.all([api(`/api/v12/stores/nearby?${qs}&limit=400`),
     api(`/api/v12/observed-prices/nearby?${qs}&max_age_days=7&limit=80`)]);
 S.stores=stores.items||[];S.observedPrices=prices.items||[];
 }catch(e){toast(e.message,true);S.stores=[];S.observedPrices=[]}}
async function loadCatalog(){try{const r=await api('/api/retail/catalog');S.catalog=r.items||[];S.catalogDate=r.snapshot_date}catch(e){S.catalog=[];toast('Catálogo no disponible: '+e.message,true)}}
async function loadSocial(){if(!S.user)return;try{S.feed=(await api('/api/v12/social')).items||[]}catch(e){toast(e.message,true)}}
async function loadOffers(){if(!S.user)return;try{S.offers=(await api('/api/v12/neighbor/offers')).items||[]}catch(e){toast(e.message,true)}}
async function loadHistory(){if(!S.user)return;try{S.purchases=(await api('/api/v12/purchases')).items||[];S.settings=await api('/api/v12/pantry/settings')}catch(e){toast(e.message,true)}}
async function start(){S.config=await api('/api/config');await loadCatalog();try{let r=await api('/api/auth/session');S.user=r.user;S.csrf=r.csrf;S.boot=await api('/api/bootstrap');await readBasket()}catch{S.user=null;S.csrf='';S.boot=null}await loadStores();render();if(S.user){loadSocial();loadOffers();loadHistory()}const hash=new URLSearchParams(location.search).get('invite');if(hash&&S.user)inviteModal(hash);}
function render(){let body='';switch(S.view){case 'home':body=homeView();break;case 'explore':body=exploreView();break;case 'map':body=mapView();break;case 'baskets':body=basketsView();break;case 'basket':body=basketView();break;case 'social':body=socialView();break;case 'circle':body=circleView();break;case 'pantry':body=pantryView();break;case 'history':body=historyView();break;case 'account':body=accountView();break;default:body=homeView()}$('#main').innerHTML=body;$('#placeLabel').textContent=placeLabel(currentPlace());if(S.view==='map')setTimeout(drawMap,120)}
function homeView(){let a=editableBasket(),top=(S.boot?.baskets||[]).slice(0,4);return `<section class="hero"><div><div class="eyebrow">Tu barrio. Tus cestas. Tu gente.</div><h1>Tu compra,<br>más inteligente.</h1><p>Guarda las listas que siempre usas, descubre supermercados cerca de tus lugares y coordina compras con personas de confianza.</p><div class="button-row"><button class="btn primary" data-view="explore">⌕ Explorar supermercados</button><button class="btn" data-action="newBasket">＋ Nueva cesta</button></div></div><div class="hero-art">🛍️</div></section>
<div class="grid cols3"><div class="metric"><strong>${S.stores.length}</strong><small>Tiendas con coordenadas en el radio seleccionado</small></div><div class="metric"><strong>${myBaskets().length}</strong><small>Cestas guardadas</small></div><div class="metric"><strong>${(S.boot?.network||[]).filter(x=>!S.placeId||x.place_id===S.placeId).length}</strong><small>Tiendas de tus redes</small></div></div>
<div class="section-title"><h2>🎧 Tu biblioteca de compras</h2><button data-view="baskets">Ver todas →</button></div>${top.length?tiles(top):empty('🧺','Tu primera cesta te espera','Organízala una vez, reutilízala siempre.','<button class="btn primary" data-action="newBasket">Crear cesta</button>')}
<div class="section-title"><h2>📍 Tu zona, tus tiendas</h2><button data-view="map">Abrir mapa →</button></div><div class="grid cols2"><section class="card"><h2>Encuentra lo que hay cerca</h2><p class="desc">Podrás seleccionar varias tiendas favoritas para cada lugar y comparar referencias sin confundir el catálogo online con el stock de esa tienda.</p><div class="button-row"><button class="btn primary" data-action="useLocation">⌖ Usar mi ubicación</button><button class="btn" data-view="explore">Ver lista</button></div></section><section class="card"><h2>🤝 Una compra, dos favores</h2><p class="desc">¿Pasas por una tienda de camino a casa? Puedes ofrecerte a llevar un recado a amistades aceptadas, sin publicar direcciones ni organizar ventas informales de alimentos perecederos.</p><button class="btn ghost" data-view="circle">Ir a Mi círculo →</button></section></div>`}
function observedPricesView(){
 let allowed=S.placeId?new Set(placeStores(S.placeId)):null;
 let rows=S.observedPrices.filter(r=>!allowed||allowed.has(r.store_id)).slice(0,12);
 return `<div class="section-title"><h2>🏷️ Precios comunicados cerca</h2><span class="tag uncertain">Últimos 7 días · aportaciones sin verificar</span></div>
 ${rows.length?`<div class="store-list">${rows.map(p=>`<article class="store-row"><span class="store-brand">€</span><div class="store-copy"><strong>${E(p.product_name)}</strong><small>${E(p.store_name)} · ${p.distance_km} km</small><small>${E(p.source_type)} · ${dateStr(p.observed_at)} · puede haber cambiado</small></div><div class="store-actions"><b>${euro(p.amount_cents)}</b></div></article>`).join('')}</div>`
 :empty('🏷️','Sin observaciones recientes en esta zona','Aún no hay suficiente información para comparar descuentos reales. Puedes registrar un precio observado desde la interfaz anterior.')}
 <div class="notice">No son ofertas oficiales, no prueban stock y pueden caducar. Un precio observado en una tienda no se extrapola a todas las tiendas de la cadena.</div>`;
}
function exploreView(){let list=S.stores.filter(s=>(!S.storeChain||s.chain===S.storeChain)&&(!S.storeQ||(`${s.name} ${s.chain} ${s.address}`).toLowerCase().includes(S.storeQ.toLowerCase())));let chainList=[...new Set(S.stores.map(s=>s.chain))].sort();let products=S.catalog.filter(p=>(!S.chain||p.chain===S.chain)&&(!S.term||(`${p.name} ${p.brand||''} ${p.category}`).toLowerCase().includes(S.term.toLowerCase())));return `${headline('CATÁLOGO LOCAL','Explorar',`Tiendas geolocalizadas y ${S.catalog.length} referencias online de muestra. Las existencias físicas no están verificadas.`, `<button data-action="useLocation" class="btn primary">⌖ Cerca de mí</button>`)}
<div class="tabs"><button class="tab ${S.activeTab==='stores'?'selected':''}" data-action="exploreTab" data-tab="stores">📍 Supermercados</button><button class="tab ${S.activeTab==='products'?'selected':''}" data-action="exploreTab" data-tab="products">🛒 Productos y precios web</button></div>
${S.activeTab==='stores'?`<section class="card"><div class="search-bar"><input class="input" id="storeSearch" placeholder="Busca una cadena o calle…" value="${E(S.storeQ)}"><select class="select" id="storeChain"><option value="">Todas las cadenas</option>${chainList.map(c=>`<option ${S.storeChain===c?'selected':''}>${E(c)}</option>`).join('')}</select><select class="select" id="radiusSelect">${[2,4,6,8,15,25].map(n=>`<option value="${n}" ${S.radius===n?'selected':''}>${n} km</option>`).join('')}</select></div><div class="button-row"><button class="btn" data-action="discover">✦ Descubrir tiendas OSM (beta)</button><button class="btn ghost" data-view="map">Ver mapa</button></div><p class="mini">El descubrimiento consulta OpenStreetMap solo cuando lo solicitas. No comprueba horarios ni existencias. Debe estar habilitado por el administrador.</p></section><div class="section-title"><h2>${list.length} establecimientos próximos</h2><span class="tag uncertain">Cobertura parcial · se amplía por zonas</span></div>${list.length?`<div class="store-list">${list.slice(0,250).map(storeCard).join('')}</div>`:empty('📍','Aún no hay tiendas geolocalizadas en este radio','Pulsa «Descubrir tiendas OSM» para importar una selección real de la zona; también puedes añadir tus propias tiendas en la interfaz anterior.')}${observedPricesView()}`:
`<section class="card"><div class="search-bar"><input id="productSearch" class="input" placeholder="Busca arroz, leche, aceite…" value="${E(S.term)}"><select class="select" id="productChain"><option value="">Todas las cadenas</option>${['DIA','Carrefour'].map(c=>`<option value="${c}" ${S.chain===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="note">Los precios son capturas publicadas de webs de cadenas en una fecha concreta. <b>No representan ofertas en directo ni surtido de una tienda física.</b></div></section><div class="section-title"><h2>${products.length} productos de muestra</h2><span class="tag">Fuente enlazada en cada ficha</span></div>${products.length?productsCards(products):empty('🔎','Sin resultados','Prueba otra categoría o cadena.')}`}`}
function mapView(){let stores=S.stores;const p=S.user?S.boot?.places||[]:[];return `${headline('MI ATLAS DE COMPRA','Tu mapa, tus lugares','Un mismo mapa para Casa, Oficina, Abuelos y tus supermercados de referencia.',`<button class="btn primary" data-action="newPlace">＋ Añadir lugar</button>`)}
<div class="two-panel"><div class="card"><div id="storeMap" class="map-frame"><div id="mapCanvas" class="map-canvas"></div><div id="mapLoading" class="map-loading">Cargando mapa…</div></div><div class="button-row" style="margin-top:13px"><button class="btn small primary" data-action="useLocation">⌖ Mi ubicación</button><button class="btn small" data-action="discover">✦ Ampliar tiendas cercanas</button></div><p class="mini">Mapa OpenFreeMap + OpenStreetMap, con atribución. El mapa requiere conexión externa; la lista funciona sin él.</p></div><div class="card"><h2>Mis lugares</h2><p class="desc">Cada lugar tiene su red de supermercados, para que tu cesta se adapte al contexto.</p>${p.length?p.map(x=>`<article class="store-row"><div class="store-brand">🏡</div><div class="store-copy"><strong>${E(x.name)}</strong><small>${x.lat!=null?'Ubicación guardada':'Sin coordenadas · configurar'}</small><small>${placeStores(x.id).length} tiendas en la red</small></div><div class="store-actions"><button class="btn small" data-action="activatePlace" data-id="${x.id}">Ver</button><button class="btn small" data-action="setPlaceLocation" data-id="${x.id}">⌖</button></div></article>`).join(''):empty('🏡','Añade Casa, Oficina o Abuelos','Puedes guardar coordenadas con el permiso de ubicación.',`<button class="btn primary" data-action="newPlace">Añadir lugar</button>`)}<div class="section-title"><h2>Tiendas próximas</h2></div><div class="store-list">${stores.slice(0,9).map(storeCard).join('')||'<p class="desc">Aún no hay tiendas cercanas cargadas.</p>'}</div></div></div>`}
let markerList=[];
function drawMap(){let target=$('#mapCanvas');if(!target)return;if(!window.maplibregl){$('#mapLoading').textContent='Mapa no disponible en este navegador. Puedes utilizar la lista de tiendas.';return}try{if(map){map.remove();map=null}map=new maplibregl.Map({container:'mapCanvas',style:'https://tiles.openfreemap.org/styles/liberty',center:[S.coords.lon,S.coords.lat],zoom:S.locationGranted?12:11,attributionControl:true});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');map.on('load',()=>{$('#mapLoading')?.remove();const places=S.boot?.places||[];for(const p of places){if(p.lat==null||p.lon==null)continue;const dot=document.createElement('div');dot.className='marker-dot home';new maplibregl.Marker({element:dot}).setLngLat([p.lon,p.lat]).setPopup(new maplibregl.Popup().setHTML(`<b>🏡 ${E(p.name)}</b><span>Tu lugar guardado</span>`)).addTo(map)}for(const s of S.stores.slice(0,250)){if(s.lat==null||s.lon==null)continue;const dot=document.createElement('div');dot.className='marker-dot';new maplibregl.Marker({element:dot}).setLngLat([s.lon,s.lat]).setPopup(new maplibregl.Popup().setHTML(`<b>${E(s.name)}</b><span>${E(s.address)}</span><br><span>${s.distance_km} km · ${E(s.source_type)}</span>`)).addTo(map)}});map.on('error',()=>{let load=$('#mapLoading');if(load)load.textContent='No se pudo cargar el mapa. La lista sigue disponible.'})}catch{$('#mapLoading').textContent='No se pudo cargar el mapa; utiliza la lista.'}}
function basketsView(){return `${headline('TU PLAYLIST DE COMPRA','Mis cestas','Compra semanal, fiesta, despensa, caprichos… cada cesta se conecta con un lugar y su red.',`<button data-action="newBasket" class="btn primary">＋ Nueva colección</button>`)}${myBaskets().length?tiles(myBaskets()):empty('🧺','Todavía no tienes cestas','Crea una lista y empieza a añadir productos en segundos.',`<button data-action="newBasket" class="btn primary">Crear cesta</button>`)}<div class="section-title"><h2>Más allá de una lista</h2></div><div class="grid cols3"><div class="card"><h2>📍 Local</h2><p class="desc">Cada cesta usa las tiendas favoritas de su lugar.</p></div><div class="card"><h2>👫 Compartida</h2><p class="desc">Compartes una lista y la editáis desde varios teléfonos.</p></div><div class="card"><h2>♻️ Reutilizable</h2><p class="desc">Terminas una compra y reactivas la cesta habitual.</p></div></div>`}
function basketView(){let b=S.basket;if(!b)return empty('🧺','Selecciona una cesta');let x=b.basket;let items=b.items||[];let canEdit=b.my_role!=='reader';return `${headline('TU COLECCIÓN',x.title,`${E(x.kind)} · ${E(S.boot?.places?.find(p=>p.id===x.place_id)?.name||'Todos los lugares')} · ${items.length} artículos`,`<button class="btn" data-action="editBasket">⚙ Configurar cesta</button>`)}
<div class="two-panel"><section class="card"><div class="button-row"><button class="btn small" data-view="baskets">← Biblioteca</button><button class="btn small ghost" data-action="shareBasket">♡ Compartir</button>${x.kind!=='actual'?`<button class="btn small" data-action="copyActual">↗ A Actual</button>`:''}</div><div class="section-title"><h2>Artículos</h2><span class="tag">${b.checked_count}/${items.length} comprados</span></div><div class="progress"><span style="width:${items.length?b.checked_count/items.length*100:0}%"></span></div>${canEdit?`<form id="quickAdd" class="quick-add"><input class="input" name="name" placeholder="Añade rápido: yogures, 2 kg tomates…" required maxlength="120"><button class="btn primary">＋ Añadir</button></form>`:''}${items.length?items.map(i=>`<div class="item-row"><input class="item-check" type="checkbox" data-action="checkItem" data-id="${i.item_kind==='free'?i.free_id:i.product_id}" data-kind="${i.item_kind}" ${i.checked?'checked':''} ${canEdit?'':'disabled'}><div class="item-name ${i.checked?'done':''}">${E(i.name)}<div class="item-sub">${E(i.format_text||i.category||'')}</div></div><div class="qtyctrl"><button ${canEdit?'':'disabled'} data-action="itemQty" data-id="${i.item_kind==='free'?i.free_id:i.product_id}" data-kind="${i.item_kind}" data-qty="${Math.max(0,i.quantity-1)}">−</button><b>${i.quantity}</b><button ${canEdit?'':'disabled'} data-action="itemQty" data-id="${i.item_kind==='free'?i.free_id:i.product_id}" data-kind="${i.item_kind}" data-qty="${i.quantity+1}">＋</button></div></div>`).join(''):empty('🛍️','Empieza por un producto','Puedes escribirlo o buscarlo en el catálogo.')}${items.length?`<div class="button-row" style="margin-top:17px"><button class="btn primary" data-action="recordPurchase">✓ He comprado esta cesta</button><button class="btn" data-action="resetChecks">↻ Reiniciar checks</button></div>`:''}</section>
<aside class="card"><h2>🧭 Plan de compra</h2><p class="desc">Lugares y supermercados que has seleccionado para esta lista.</p><p><span class="tag">${E(S.boot?.places?.find(p=>p.id===x.place_id)?.name||'Sin lugar fijo')}</span></p><div class="store-list">${(b.preferred_store_ids||[]).map(id=>S.boot?.stores?.find(s=>s.id===id)).filter(Boolean).map(s=>`<div class="store-row">${storeBadge(s)}<div class="store-copy"><strong>${E(s.name)}</strong><small>${E(s.address)}</small></div></div>`).join('')||'<p class="mini">Selecciona varias tiendas desde Configurar cesta.</p>'}</div><div class="note" style="margin-top:15px">Los precios web publicados por cadena no demuestran disponibilidad ni promociones en estas sucursales.</div><button data-view="explore" class="btn ghost" style="margin-top:12px">⌕ Buscar productos</button></aside></div>`}
function pantryView(){let rows=S.boot?.pantry||[];return `${headline('EVITA COMPRAR DE MÁS','Mi despensa','Cuando confirmes que has recibido una compra, puedes pasar sus productos aquí automáticamente.',`<button data-action="newPantry" class="btn primary">＋ Añadir alimento</button>`)}<section class="card"><div class="button-row"><label style="display:flex;gap:9px;align-items:center;font-size:12px"><input type="checkbox" id="autoPantry" ${S.settings.auto_pantry?'checked':''}> Añadir a mi despensa por defecto tras confirmar recepción</label></div><p class="mini">Nunca se mueve una compra a la despensa antes de confirmar que la has recibido.</p></section><div class="section-title"><h2>${rows.filter(r=>r.state==='active').length} alimentos registrados</h2></div><section class="card">${rows.filter(r=>r.state==='active').map(i=>`<div class="item-row"><span style="font-size:23px">🥬</span><div class="item-name">${E(i.custom_name||i.product_name)}<div class="item-sub">${i.quantity} ${E(i.unit)} · ${i.expires_on?'Fecha registrada: '+dateStr(i.expires_on):'Caducidad no registrada'}</div></div><button class="btn small" data-action="usePantry" data-id="${i.id}">Consumido</button></div>`).join('')||empty('🥬','Tu despensa está vacía','Añade alimentos manualmente o desde una compra confirmada.')}</section>`}
function historyView(){return `${headline('COMPRA SIN FRICCIÓN','Historial de compras','Registra tu compra física, añade productos extra y decide qué entra en tu despensa.',`<button class="btn primary" data-action="recordPurchase">＋ Registrar compra</button>`)}<div class="section-title"><h2>Compras registradas</h2></div><div class="card">${S.purchases.map(p=>`<div class="item-row"><span style="font-size:26px">🧾</span><div class="item-name">${E(p.basket_title||'Compra personal')}<div class="item-sub">${dateStr(p.created_at)} · ${p.received_at?'Recibida':'Pendiente de recepción'} ${p.pantry_added_at?'· Trasladada a despensa':''}</div></div><b>${euro(p.paid_cents)}</b>${!p.received_at?`<button class="btn small primary" data-action="receivePurchase" data-id="${p.id}">Confirmar recepción</button>`:!p.pantry_added_at?`<button class="btn small" data-action="addPurchasePantry" data-id="${p.id}">A despensa</button>`:''}</div>`).join('')||empty('🧾','Todavía no tienes compras','Puedes registrar la cesta Actual + otros productos que hayas comprado por tu cuenta.')}</div>`}
function socialView(){if(!S.user)return guestView('La comunidad');let labels={oferta:'🏷️ Oferta observada',repuesto:'📦 Reposición',agotado:'🚫 Agotado',nuevo:'✨ Producto nuevo',retirado:'👋 Producto retirado',valoracion:'⭐ Valoración',receta:'🍲 Receta',consejo:'💡 Consejo'};return `${headline('SHOPPER LIVE','La comunidad','Noticias locales, experiencias y valoraciones contadas por personas. Cada aviso indica cuándo y quién lo observó.',`<button class="btn primary" data-action="newPost">＋ Publicar novedad</button>`)}<div class="notice" style="margin-bottom:15px">Las publicaciones son colaborativas: ni SHOPPER ni las tiendas confirman automáticamente los precios, descuentos o existencias. Los avisos de stock y descuentos caducan a las 12 h.</div><div class="two-panel"><div><div class="tabs">${['','oferta','nuevo','valoracion','receta'].map(k=>`<button class="tab ${S.socialFilter===k||(!S.socialFilter&&!k)?'selected':''}" data-action="socialFilter" data-kind="${k}">${k?(labels[k]||k):'Todos'}</button>`).join('')}</div>${S.feed.filter(p=>!S.socialFilter||p.kind===S.socialFilter).map(p=>`<article class="post"><div class="post-head"><div class="post-avatar">${labels[p.kind]?.split(' ')[0]||'🛍️'}</div><div class="post-author"><strong>${E(p.author_name)}</strong><small>${dateStr(p.created_at)} · ${p.visibility==='friends'?'Solo amistades':'Comunidad'}</small></div><span class="tag uncertain">Observación personal</span></div><span class="eyebrow">${labels[p.kind]||E(p.kind)}</span><h3>${E(p.title)}</h3><p>${E(p.body)}</p><div class="mini">${p.store_name?'📍 '+E(p.store_name)+' · ':''}${p.product_name?'📦 '+E(p.product_name):''}${p.price_cents?' · '+euro(p.price_cents):''}</div><div class="post-actions"><button class="${p.my_reaction==='util'?'active':''}" data-action="react" data-id="${p.id}" data-kind="util">👍 Útil · ${p.useful||0}</button><button class="${p.my_reaction==='interesante'?'active':''}" data-action="react" data-id="${p.id}" data-kind="interesante">✨ Interesante</button><button class="${p.my_reaction==='dudo'?'active':''}" data-action="react" data-id="${p.id}" data-kind="dudo">¿Seguro?</button><button data-action="comments" data-id="${p.id}">💬 ${p.comments||0} comentarios</button><button data-action="flagPost" data-id="${p.id}">⋯ Reportar</button></div></article>`).join('')||empty('🪄','La comunidad está empezando','Comparte una valoración o una novedad real para inaugurar el feed.')}</div><aside class="card"><h2>Una comunidad útil</h2><p class="desc">Comparte lo que has observado, no lo que supones. Indica la tienda concreta y el momento.</p><div class="button-row"><button class="btn ghost" data-action="newPost">Crear publicación</button><button class="btn" data-view="circle">Ofrecer una mano</button></div><div class="note" style="margin-top:17px">Red social en beta privada. Sin fotos, mensajes directos de desconocidos ni exposición de direcciones privadas.</div></aside></div>`}
function circleView(){if(!S.user)return guestView('Mi círculo');return `${headline('MI BARRIO + MI GENTE','Ayudarnos es fácil','Puedes coordinar recados entre contactos aceptados. Nunca hacemos públicas las direcciones de personas que necesiten ayuda.',`<button class="btn primary" data-action="newOffer">↗ Voy al súper</button>`)}<div class="grid cols2"><section class="card"><h2>🤝 Pasaré por un supermercado</h2><p class="desc">Comparte con tus amistades aceptadas un aviso temporal: "paso por DIA y puedo traer dos artículos". La compra y el reembolso se coordinan fuera de esta beta.</p><button class="btn ghost" data-action="newOffer">Publicar que puedo ayudar</button></section><section class="card"><h2>♡ Cestas de confianza</h2><p class="desc">Comparte una cesta familiar y envía la lista a quien pueda pasar por la tienda. No hay encargos profesionales todavía.</p><button class="btn" data-action="friendInvite">Invitar amistad</button></section></div><div class="section-title"><h2>Ofrecimientos de mi círculo</h2></div><div class="card">${S.offers.map(o=>`<div class="item-row"><span style="font-size:27px">🛍️</span><div class="item-name">${E(o.author_name)} · ${E(o.area_label)}<div class="item-sub">${E(o.note)} · Hasta ${new Date(o.until_at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</div></div><span class="tag">${o.status==='open'?'Disponible':o.status}</span>${o.status==='open'&&o.creator_id!==S.user.id?`<button class="btn primary small" data-action="acceptOffer" data-id="${o.id}">Aceptar</button>`:''}${o.creator_id===S.user.id&&o.status==='open'?`<button class="btn small" data-action="cancelOffer" data-id="${o.id}">Cancelar</button>`:''}${o.status==='accepted'&&(o.creator_id===S.user.id||o.accepted_by===S.user.id)?`<button class="btn small" data-action="completeOffer" data-id="${o.id}">Completado</button>`:''}</div>`).join('')||empty('🤝','Tu círculo está tranquilo','Invita a una persona de confianza y podrás ofrecerte a traer un recado.')}</div><div class="notice" style="margin-top:16px">Piloto de colaboración entre amistades, no marketplace de productos ni transporte comercial. No ofrece el reparto informal de carnes refrigeradas o congelados sin condiciones de higiene, temperatura y responsabilidad verificadas.</div>`}
function accountView(){return `${headline('TU PERFIL','Mi cuenta','Una única identidad para listas, lugares y comunidad.')}${S.user?`<div class="card"><h2>Hola, ${E(S.user.display_name)}</h2><p class="desc">Usuario: ${E(S.user.username)}</p><div class="button-row"><button class="btn" data-action="friendInvite">♡ Invitar amigos</button><button class="btn" data-view="history">🧾 Historial</button><button class="btn warn" data-action="logout">Cerrar sesión</button></div></div>`:`<div class="card"><h2>Entra para guardar tu universo SHOPPER</h2><p class="desc">Puedes explorar el catálogo y los supermercados sin cuenta. El registro utiliza un código privado durante la beta.</p><div class="button-row"><button class="btn primary" data-action="login">Entrar</button><button class="btn" data-action="register">Crear cuenta</button></div></div>`}<div class="section-title"><h2>Transparencia de datos</h2></div><div class="card"><p class="desc">Mapa y tiendas de OpenStreetMap bajo ODbL; referencias web comerciales fechadas; avisos comunitarios no verificados. Ninguna compra o recogida está conectada con las cajas de supermercados.</p><div class="button-row"><a href="/previous" class="btn">Versión 11 anterior</a><a href="/classic" class="btn">Herramientas avanzadas</a><a href="/api/v12/sources" class="btn" target="_blank">Ver fuentes</a></div></div>`}
function guestView(title){return `${headline('PARA TU GENTE',title,'Accede para guardar y compartir información con tus amistades.')}${empty('🔐','Necesitas una cuenta para esta función','En la beta se necesita un código de alta privado.','<button class="btn primary" data-action="register">Crear cuenta</button>')}`}
function authModal(mode){let register=mode==='register';modal(`<div class="eyebrow">ACCESO PRIVADO</div><h2>${register?'Crear cuenta SHOPPER':'Bienvenido de nuevo'}</h2><p class="desc">${register?'Tu código privado de alta debe coincidir con el configurado en Railway. No es tu contraseña.':'Tus cestas y redes se guardan de forma privada.'}</p><form id="authForm" class="form"><input type="hidden" name="register" value="${register?'1':'0'}"><label>Usuario<input class="input" name="username" required minlength="3" maxlength="24" pattern="[a-zA-Z0-9._-]+" autocomplete="username"></label>${register?`<label>Nombre visible<input class="input" name="display_name" required minlength="2" maxlength="60"></label>`:''}<label>Contraseña<input class="input" type="password" name="password" required minlength="12" autocomplete="${register?'new-password':'current-password'}"></label>${register?`<label>Código privado de alta<input class="input" type="password" name="signup_code" minlength="16" required autocomplete="off"></label>`:''}<button class="btn primary">${register?'Crear mi cuenta':'Entrar'}</button></form><button class="btn ghost" data-action="${register?'login':'register'}">${register?'Ya tengo cuenta':'Quiero crear cuenta'}</button>`)}
function placeModal(){if(authRequired())return;const p=S.boot.places||[];modal(`<div class="eyebrow">TUS LUGARES</div><h2>Cambia tu zona</h2><p class="desc">Cada lugar tiene su propia selección de supermercados favoritos.</p><div class="store-list">${p.map(x=>`<button class="store-row" data-action="activatePlace" data-id="${x.id}"><span>🏡</span><span style="flex:1;text-align:left;font-weight:800">${E(x.name)}</span>${S.placeId===x.id?'✓':'→'}</button>`).join('')}</div><div class="button-row" style="margin-top:15px"><button class="btn primary" data-action="newPlace">＋ Añadir lugar</button><button class="btn" data-action="resetPlace">Todos mis lugares</button></div>`)}
function newPlaceModal(){if(authRequired())return;modal(`<div class="eyebrow">MI MAPA</div><h2>Nuevo lugar</h2><p class="desc">Casa, Oficina, Pueblo, Abuelos… Las coordenadas son opcionales y privadas.</p><form class="form" id="newPlaceForm"><label>Nombre<input class="input" name="name" required minlength="2" maxlength="80" placeholder="Casa Madrid"></label><label>Dirección (opcional)<input class="input" name="address" maxlength="220" placeholder="Solo visible en tu cuenta"></label><label class="check-grid"><span><input type="checkbox" name="here"> Guardar mi ubicación actual si doy permiso</span></label><button class="btn primary">Crear lugar</button></form>`)}
function basketEditor(){if(authRequired())return;let b=S.basket?.basket||null;let editing=b&&S.view==='basket';let places=S.boot.places||[];let p=editing?b.place_id:S.placeId;let kinds=['ocasional','semanal','mensual','evento'];let topics=['Alimentación','Hogar','Salud','Fiesta','Mascotas','Niños','Ahorro'];let existing=editing?S.basket?.preferred_store_ids||[]:[];let selections=editing?S.basket?.topics||[]:[];modal(`<div class="eyebrow">🎧 TU COLECCIÓN</div><h2>${editing?'Editar cesta':'Crear cesta nueva'}</h2><form class="form" id="basketEditor"><input name="id" type="hidden" value="${editing?b.id:''}"><label>Nombre de la cesta<input class="input" name="title" required maxlength="90" value="${E(editing?b.title:'')}" placeholder="Mi compra de los domingos"></label><div class="form-rows"><label>Tipo<select class="select" id="kindField" name="kind">${kinds.map(k=>`<option value="${k}" ${editing&&b.kind===k?'selected':''}>${k==='evento'?'🎉 Evento':k==='semanal'?'📅 Semanal':k==='mensual'?'🧼 Mensual':'🍫 Ocasional'}</option>`).join('')}</select></label><label>Portada<select class="select" name="cover_emoji">${['🧺','🥑','🍫','🎉','🍞','🏡','🍓','🧼','🍝'].map(e=>`<option ${editing&&b.cover_emoji===e?'selected':''}>${e}</option>`).join('')}</select></label></div><label>Lugar asociado<select class="select" id="basketPlaceField" name="place_id"><option value="">Sin lugar fijo</option>${places.map(x=>`<option value="${x.id}" ${p===x.id?'selected':''}>${E(x.name)}</option>`).join('')}</select></label><div id="eventField" class="${editing&&b.kind==='evento'?'':'hidden'}"><label>Fecha del evento<input class="input" name="event_on" type="date" value="${editing&&b.event_on?b.event_on:''}"></label></div><label>Temas (varios posibles)<div class="check-grid">${topics.map(t=>`<label><input type="checkbox" name="topics" value="${t}" ${selections.includes(t)?'checked':''}>${t}</label>`).join('')}</div></label><div><div class="eyebrow">SUPERMERCADOS DE ESTE LUGAR (SELECCIÓN MÚLTIPLE)</div><div id="basketStoreChoices" class="check-grid">${storeChoices(p,existing)}</div></div><div class="form-rows"><label>Color<select class="select" name="accent">${['sage','peach','lavender','ocean','lemon','rose'].map(c=>`<option value="${c}" ${editing&&b.accent===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Presupuesto objetivo (€)<input class="input" type="number" name="budget" step="0.01" min="0" value="${editing&&b.budget_cents!=null?(b.budget_cents/100).toFixed(2):''}"></label></div><label>Notas<textarea class="input" rows="2" name="notes" maxlength="700">${E(editing?b.notes:'')}</textarea></label><button class="btn primary">${editing?'Guardar cambios':'Crear mi colección'}</button></form>`);syncEventField()}
function storeChoices(pid,selected=[]){const ids=placeStores(pid);return pid?ids.length?ids.map(id=>S.boot.stores.find(s=>s.id===id)).filter(Boolean).map(s=>`<label><input type="checkbox" name="store_ids" value="${s.id}" ${selected.includes(s.id)?'checked':''}>${E(s.name)}</label>`).join(''):'<p class="mini">Aún no has añadido tiendas a esta red. Ve a Mapa / Supermercados y guárdalas. </p>':'<p class="mini">Selecciona un lugar para escoger supermercados de referencia.</p>'}
function syncEventField(){let t=$('#kindField')?.value;let f=$('#eventField');if(f){f.classList.toggle('hidden',t!=='evento');let input=f.querySelector('input');if(t!=='evento')input.value=''}}
function purchaseModal(){if(authRequired())return;let bs=myBaskets();let sidChoices=(S.boot?.stores||[]).slice(0,200);modal(`<div class="eyebrow">REGISTRA UNA COMPRA REALIZADA</div><h2>¿Qué has comprado?</h2><p class="desc">Puedes partir de una cesta y añadir productos que hayas cogido al pasar por el supermercado. Ningún importe se considera verificado por la tienda.</p><form id="purchaseForm" class="form"><label>Cesta de origen<select class="select" name="basket_id"><option value="">Solo productos extra</option>${bs.map(b=>`<option value="${b.id}" ${b.id===S.basketId?'selected':''}>${E(b.title)}</option>`).join('')}</select></label><label><span>Solo incluir los artículos marcados como comprados</span><span><input type="checkbox" name="checked_only"> Sí, excluir los no marcados</span></label><label>Productos extra (uno por línea)<textarea name="extras" class="input" rows="3" placeholder="Pan integral; 1; ud&#10;Tomates; 2; kg"></textarea><span class="small-print">Formato: nombre; cantidad; unidad (ud, kg, g, l, ml, pack)</span></label><div class="form-rows"><label>Importe real pagado (€)<input type="number" name="paid" class="input" step="0.01" min="0" required placeholder="24,50"></label><label>Tiempo empleado (min)<input type="number" name="minutes" class="input" min="0" max="1440" placeholder="35"></label></div><label>Tiendas visitadas (varias posibles)<div class="check-grid" style="max-height:160px;overflow:auto">${sidChoices.map(s=>`<label><input type="checkbox" name="store_ids" value="${s.id}">${E(s.name)}</label>`).join('')}</div></label><label><span><input type="checkbox" name="received" checked> Ya tengo la compra y confirmo su recepción</span></label><label>Después de recibir<select class="select" name="pantry_mode"><option value="default">Usar mi preferencia de despensa</option><option value="add">Añadir automáticamente a despensa</option><option value="skip">No añadir a despensa</option></select></label><button class="btn primary">Guardar compra</button></form><p class="mini">Esta función registra una compra realizada por ti: no envía un encargo ni cobra dinero.</p>`)}
function newPantryModal(){if(authRequired())return;modal(`<div class="eyebrow">LO QUE YA TIENES</div><h2>Registrar alimento</h2><form id="pantryForm" class="form"><label>Producto<input class="input" name="name" required maxlength="100"></label><div class="form-rows"><label>Cantidad<input class="input" name="quantity" type="number" min=".01" step=".01" value="1" required></label><label>Unidad<select name="unit" class="select">${['ud','kg','g','l','ml'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><label>Fecha del alimento (opcional)<input type="date" class="input" name="expires"></label><button class="btn primary">Añadir a despensa</button></form>`)}
function postModal(){if(authRequired())return;modal(`<div class="eyebrow">COMPÁRTELO CON TU ZONA</div><h2>Publicar una novedad</h2><form id="postForm" class="form"><div class="form-rows"><label>Qué compartes<select class="select" name="kind" id="postKind">${[['oferta','🏷️ Precio observado'],['repuesto','📦 Reposición'],['agotado','🚫 Agotado'],['nuevo','✨ Producto nuevo'],['retirado','👋 Ya no se vende'],['valoracion','⭐ Valoración'],['receta','🍲 Receta'],['consejo','💡 Consejo']].map(k=>`<option value="${k[0]}">${k[1]}</option>`).join('')}</select></label><label>Visibilidad<select class="select" name="visibility"><option value="community">Toda la comunidad de la beta</option><option value="friends">Solo amistades</option></select></label></div><label>Título<input class="input" name="title" required maxlength="100" placeholder="He visto una oferta de yogures"></label><label>Tu observación<textarea class="input" name="body" required maxlength="800" rows="3" placeholder="Qué viste, cuándo y por qué puede ser útil"></textarea></label><label>Tienda (opcional)<select class="select" name="store_id"><option value="">Sin tienda concreta</option>${(S.boot?.stores||[]).slice(0,500).map(x=>`<option value="${x.id}">${E(x.name)}</option>`).join('')}</select></label><label id="priceField">Precio observado (€) para ofertas<input class="input" type="number" name="price" min="0.01" step="0.01" placeholder="Ej. 2,45" required></label><button class="btn primary">Publicar con fecha y fuente personal</button></form>`)}
function commentsModal(id){if(authRequired())return;modal(`<div class="eyebrow">CONVERSACIÓN</div><h2>Comentarios</h2><div id="commentsList" class="loading">Cargando…</div><form id="commentForm" class="form"><input type="hidden" name="post_id" value="${id}"><label>Tu respuesta<textarea class="input" name="body" rows="3" required minlength="2" maxlength="400"></textarea></label><button class="btn primary">Comentar</button></form>`);api(`/api/v12/social/${id}/comments`).then(r=>$('#commentsList').innerHTML=r.items.length?r.items.map(c=>`<div class="item-row"><span>💬</span><div class="item-name">${E(c.author_name)}<div class="item-sub">${E(c.body)} · ${dateStr(c.created_at)}</div></div></div>`).join(''):'<p class="desc">Sé la primera persona en comentar.</p>').catch(e=>toast(e.message,true))}
function offerModal(){if(authRequired())return;modal(`<div class="eyebrow">CÍRCULO DE CONFIANZA</div><h2>Voy a pasar por un súper</h2><p class="desc">Tus amigos aceptados podrán ver tu ofrecimiento mientras esté vigente. Evita direcciones y datos personales.</p><form id="offerForm" class="form"><label>Zona general<input class="input" name="area" required maxlength="75" placeholder="Alcobendas · Madrid norte"></label><label>Tienda (opcional)<select class="select" name="store_id"><option value="">Por mi zona</option>${(S.boot?.stores||[]).slice(0,500).map(s=>`<option value="${s.id}">${E(s.name)}</option>`).join('')}</select></label><label>Qué podrías traer<textarea class="input" name="note" required minlength="8" maxlength="260" rows="3" placeholder="Voy a comprar para mí, puedo traer un par de artículos sin desviar mi ruta."></textarea></label><label>Hasta cuándo<select class="select" name="minutes">${[15,30,45,60,90,120,180].map(n=>`<option value="${n}" ${n===60?'selected':''}>Próximos ${n} min</option>`).join('')}</select></label><button class="btn primary">Avisar a mis amigos</button></form><div class="notice">La beta no permite venta ni entrega profesional; no anuncies transporte de carnes u otros alimentos que precisen frío sin medios adecuados.</div>`)}
function inviteModal(code){modal(`<div class="eyebrow">COMPARTIR CESTAS</div><h2>Aceptar invitación</h2><p class="desc">Acceso de un solo uso entre cuentas.</p><form id="inviteForm" class="form"><label>Código<input class="input" name="code" required value="${E(code||'')}"></label><button class="btn primary">Aceptar invitación</button></form>`)}
async function getGPS(){return new Promise((resolve,reject)=>{if(!navigator.geolocation){reject(Error('Este navegador no admite geolocalización'));return}navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lon:p.coords.longitude}),()=>reject(Error('Permiso denegado. Puedes seguir explorando Madrid sin geolocalización.')),{enableHighAccuracy:false,timeout:10000,maximumAge:180000})})}
async function useLocation(storeInPlaceId=null){let p=await getGPS();S.coords=p;S.locationGranted=true;if(storeInPlaceId){await api(`/api/v12/places/${storeInPlaceId}/coordinates`,'PATCH',p);await refresh()}await loadStores();closeModal();toast('Tiendas ordenadas por proximidad a tu ubicación');render()}
function currentBasketId(){return S.basketId||editableBasket()?.id}
async function action(type,el){switch(type){case 'register':authModal('register');return;case 'login':authModal('login');return;
case 'logout':await api('/api/auth/logout','POST',{});S.user=null;S.csrf='';S.boot=null;S.basket=null;S.basketId=null;S.placeId=null;closeModal();nav('home');toast('Sesión cerrada');return;
case 'choosePlace':placeModal();return;case 'resetPlace':S.placeId=null;closeModal();render();return;
case 'newPlace':newPlaceModal();return;case 'newBasket':basketEditor();return;case 'editBasket':basketEditor();return;
case 'activatePlace':{let id=Number(el.dataset.id);let p=S.boot.places.find(p=>p.id===id);S.placeId=id;if(p?.lat!=null){S.coords={lat:p.lat,lon:p.lon};S.locationGranted=false;await loadStores()}closeModal();render();toast('Lugar: '+p.name);return}
case 'setPlaceLocation':await useLocation(Number(el.dataset.id));return;case 'useLocation':await useLocation();return;
case 'discover':{if(authRequired())return;if(!confirm('Se enviará esta ubicación aproximada a un servidor externo de OpenStreetMap para buscar tiendas. Solo en beta privada. ¿Continuar?'))return;const r=await api(`/api/v12/stores/discover?radius_km=${Math.min(S.radius,8)}`,'POST',S.coords);await loadStores();await refresh();toast('Directorio actualizado: '+r.added+' tiendas añadidas');render();return}
case 'exploreTab':S.activeTab=el.dataset.tab;render();return;
case 'networkToggle':{if(authRequired())return;if(!S.placeId){toast('Selecciona antes un lugar desde la barra superior',true);return}await api(`/api/places/${S.placeId}/stores`,'POST',{store_id:Number(el.dataset.id),save:el.dataset.save==='1'});await refresh();toast('Red personal actualizada');return}
case 'addProduct':{if(authRequired()){S.pendingProduct=Number(el.dataset.id);return}let bid=currentBasketId();if(!bid||!Number(el.dataset.id)){toast('Selecciona una cesta editable y un producto válido',true);return}const prev=S.basket?.basket?.id===bid?S.basket.items.find(i=>i.product_id===Number(el.dataset.id)):null;await api(`/api/baskets/${bid}/items/${el.dataset.id}`,'PUT',{quantity:Number(prev?.quantity||0)+1});await refresh();toast('Producto añadido a tu cesta');return}
case 'checkItem':{let id=Number(el.dataset.id);let typ=el.dataset.kind;let row=S.basket?.items.find(i=>typ==='free'?i.free_id===id:i.product_id===id);if(!row)return;if(typ==='free')await api(`/api/baskets/${S.basketId}/free-items/${id}`,'PATCH',{checked:!row.checked});else await api(`/api/baskets/${S.basketId}/items/${id}/check`,'PATCH',{checked:!row.checked});await refresh();return}
case 'itemQty':{let id=Number(el.dataset.id),n=Number(el.dataset.qty),typ=el.dataset.kind;if(typ==='free')await api(`/api/baskets/${S.basketId}/free-items/${id}`,'PATCH',{quantity:n});else await api(`/api/baskets/${S.basketId}/items/${id}`,'PUT',{quantity:n});await refresh();return}
case 'shareBasket':{if(authRequired())return;const r=await api(`/api/baskets/${S.basketId}/invite`,'POST',{role:'editor'});let link=new URL(location.origin+'/');link.searchParams.set('invite',r.code);modal(`<div class="eyebrow">INVITACIÓN PRIVADA</div><h2>Comparte tu cesta</h2><p class="desc">Enlace de un solo uso y caducidad limitada. No lo publiques en redes.</p><input class="input" readonly id="inviteLink" value="${E(link.toString())}"><button class="btn primary" data-action="copyInvite">Copiar enlace</button>`);return}
case 'copyInvite':{let i=$('#inviteLink');try{await navigator.clipboard.writeText(i.value);toast('Enlace copiado')}catch{i.select();toast('Selecciona y copia el enlace')};return}
case 'friendInvite':{if(authRequired())return;const r=await api('/api/friends/invite','POST',{});let link=new URL(location.origin+'/');link.searchParams.set('invite',r.code);modal(`<h2>Invita a tu círculo</h2><p class="desc">Comparte este enlace con una persona de confianza.</p><input class="input" id="inviteLink" value="${E(link.toString())}" readonly><button class="btn primary" data-action="copyInvite">Copiar enlace</button>`);return}
case 'resetChecks':await api(`/api/baskets/${S.basketId}/reset-checks`,'POST',{});await refresh();toast('Lista lista para repetir');return;
case 'copyActual':await api(`/api/baskets/${S.basketId}/copy-to-actual`,'POST',{});await refresh();toast('Productos copiados a la cesta Actual');return;
case 'recordPurchase':purchaseModal();return;case 'receivePurchase':case 'addPurchasePantry':{let id=Number(el.dataset.id);const r=await api(`/api/v12/purchases/${id}/receive`,'POST',{pantry_mode:type==='addPurchasePantry'?'add':'default'});await loadHistory();await refresh();toast('Compra recibida: '+r.pantry_added+' alimentos pasaron a despensa');return}
case 'newPantry':newPantryModal();return;case 'usePantry':await api(`/api/pantry/${el.dataset.id}`,'PATCH',{state:'used'});await refresh();toast('Marcado como consumido');return;
case 'newPost':postModal();return;case 'socialFilter':S.socialFilter=el.dataset.kind;render();return;
case 'react':{if(authRequired())return;let post=S.feed.find(p=>p.id===Number(el.dataset.id));await api(`/api/v12/social/${el.dataset.id}/react`,'POST',{kind:post?.my_reaction===el.dataset.kind?'none':el.dataset.kind});await loadSocial();render();return}
case 'comments':commentsModal(Number(el.dataset.id));return;case 'flagPost':{let reason=prompt('Motivo: spam / falso / abusivo / datos_personales','falso');if(!reason)return;await api(`/api/v12/social/${el.dataset.id}/flag`,'POST',{reason});toast('Publicación reportada');return}
case 'newOffer':offerModal();return;case 'acceptOffer':case 'cancelOffer':case 'completeOffer':{let a=type==='acceptOffer'?'accept':type==='cancelOffer'?'cancel':'complete';await api(`/api/v12/neighbor/offers/${el.dataset.id}/action`,'POST',{action:a});await loadOffers();render();return}
default:toast('Función no disponible',true)}}
function formValues(form){let f=new FormData(form),out={};for(let[k,v]of f.entries()){if(k in out){if(!Array.isArray(out[k]))out[k]=[out[k]];out[k].push(v)}else out[k]=v}return out}
function selected(form,name){return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map(n=>n.value)}
async function submit(form){let x=formValues(form),id=form.id;
if(id==='authForm'){let reg=x.register==='1';let r=await api(reg?'/api/auth/register':'/api/auth/login','POST',{username:x.username,password:x.password,...(reg?{display_name:x.display_name,signup_code:x.signup_code||''}:{})});S.user=r.user;S.csrf=r.csrf;S.boot=await api('/api/bootstrap');await readBasket();await loadHistory();await loadSocial();await loadOffers();closeModal();nav('baskets');toast(reg?'Cuenta creada':'Sesión iniciada');let code=new URLSearchParams(location.search).get('invite');if(code)inviteModal(code);if(S.pendingProduct){let pending=S.pendingProduct;S.pendingProduct=null;await action('addProduct',{dataset:{id:pending}})}return}
if(id==='newPlaceForm'){let placeData={name:x.name,address:x.address||null};if(x.here){Object.assign(placeData,await getGPS())}let r=await api('/api/places','POST',placeData);S.placeId=r.id;if(placeData.lat){S.coords={lat:placeData.lat,lon:placeData.lon};await loadStores()}closeModal();await refresh();nav('map');toast('Lugar creado; añade los supermercados de tu zona');return}
if(id==='basketEditor'){let editing=!!x.id,kind=x.kind;let d={title:x.title,kind,cover_emoji:x.cover_emoji,place_id:x.place_id?Number(x.place_id):null,event_on:kind==='evento'?x.event_on||null:null,topics:selected(form,'topics'),preferred_store_ids:selected(form,'store_ids').map(Number),accent:x.accent,budget_cents:x.budget?Math.round(Number(x.budget)*100):null,notes:x.notes||''};let r=await api(editing?`/api/baskets/${x.id}`:'/api/baskets',editing?'PATCH':'POST',d);S.basketId=editing?Number(x.id):r.id;closeModal();await refresh();nav('basket');toast(editing?'Cesta actualizada':'Cesta creada');return}
if(id==='quickAdd'){await api(`/api/baskets/${S.basketId}/free-items`,'POST',{title:x.name,quantity:1});await refresh();return}
if(id==='purchaseForm'){let extras=[];for(const line of (x.extras||'').split('\n').map(s=>s.trim()).filter(Boolean)){let [name,q,unit]=line.split(';').map(s=>s.trim());extras.push({name,quantity:Number(q||1),unit:unit||'ud'})}let d={basket_id:x.basket_id?Number(x.basket_id):null,store_ids:selected(form,'store_ids').map(Number),paid_cents:Math.round(Number(x.paid)*100),minutes_spent:x.minutes?Number(x.minutes):null,extras,received:!!x.received,pantry_mode:x.pantry_mode,checked_only:!!x.checked_only};let r=await api('/api/v12/purchases','POST',d);closeModal();await loadHistory();await refresh();nav('history');toast('Compra guardada · '+r.pantry_added+' productos a despensa');return}
if(id==='pantryForm'){await api('/api/pantry','POST',{custom_name:x.name,quantity:Number(x.quantity),unit:x.unit,expires_on:x.expires||null});closeModal();await refresh();nav('pantry');toast('Alimento añadido');return}
if(id==='postForm'){let d={kind:x.kind,title:x.title,body:x.body,visibility:x.visibility,store_id:x.store_id?Number(x.store_id):null,price_cents:x.kind==='oferta'?Math.round(Number(x.price)*100):null};await api('/api/v12/social','POST',d);closeModal();await loadSocial();nav('social');toast('Publicado como observación personal no verificada');return}
if(id==='commentForm'){await api(`/api/v12/social/${x.post_id}/comments`,'POST',{body:x.body});await loadSocial();commentsModal(Number(x.post_id));toast('Comentario publicado');return}
if(id==='offerForm'){await api('/api/v12/neighbor/offers','POST',{area_label:x.area,note:x.note,store_id:x.store_id?Number(x.store_id):null,minutes_available:Number(x.minutes)});closeModal();await loadOffers();nav('circle');toast('Tus amistades pueden ver el ofrecimiento');return}
if(id==='inviteForm'){await api('/api/invitations/redeem','POST',{code:x.code});history.replaceState(null,'','/');closeModal();await refresh();nav('baskets');toast('Invitación aceptada');return}}
document.addEventListener('click',async ev=>{let t=ev.target.closest('[data-view],[data-action],[data-open-basket]');if(!t)return;ev.preventDefault();try{if(t.dataset.view){nav(t.dataset.view);if(t.dataset.view==='social')await loadSocial().then(render);if(t.dataset.view==='circle')await loadOffers().then(render);if(t.dataset.view==='history'||t.dataset.view==='pantry')await loadHistory().then(render);return}if(t.dataset.openBasket){S.basketId=Number(t.dataset.openBasket);await readBasket();nav('basket');return}if(t.dataset.action)await action(t.dataset.action,t)}catch(e){toast(e.message,true)}});
document.addEventListener('submit',async ev=>{let f=ev.target;if(!f.id)return;ev.preventDefault();let b=f.querySelector('button[type=submit],button:not([type])');if(b)b.disabled=true;try{await submit(f)}catch(e){toast(e.message,true)}finally{if(b&&b.isConnected)b.disabled=false}});
document.addEventListener('change',async ev=>{let t=ev.target;try{if(t.id==='kindField'){syncEventField()}if(t.id==='basketPlaceField'){$('#basketStoreChoices').innerHTML=storeChoices(Number(t.value),[])}if(t.id==='radiusSelect'){S.radius=Number(t.value);await loadStores();render()}if(t.id==='storeChain'){S.storeChain=t.value;render()}if(t.id==='productChain'){S.chain=t.value;render()}if(t.id==='postKind'){const price=$('#priceField');if(price){price.classList.toggle('hidden',t.value!=='oferta');price.querySelector('input').required=t.value==='oferta'}}if(t.id==='autoPantry'){await api('/api/v12/pantry/settings','PUT',{auto_pantry:t.checked});S.settings.auto_pantry=t.checked;toast('Preferencia guardada')}}catch(e){toast(e.message,true)}});
document.addEventListener('input',ev=>{let t=ev.target;if(['storeSearch','productSearch'].includes(t.id)){clearTimeout(searchTimer);let text=t.value;searchTimer=setTimeout(()=>{if(t.id==='storeSearch')S.storeQ=text;else S.term=text;let pos=t.selectionStart;render();let i=$('#'+t.id);i?.focus();i?.setSelectionRange(pos,pos)},250)}});
document.addEventListener('keydown',async ev=>{if(ev.key==='Escape')closeModal();if((ev.key==='Enter'||ev.key===' ')&&ev.target.hasAttribute('data-open-basket')){ev.preventDefault();S.basketId=Number(ev.target.dataset.openBasket);await readBasket();nav('basket')}});
$('#closeModal').addEventListener('click',closeModal);$('#modalBack').addEventListener('click',ev=>{if(ev.target.id==='modalBack')closeModal()});
window.addEventListener('offline',()=>toast('Sin conexión. Los cambios no se guardan hasta reconectar.',true));
window.addEventListener('online',()=>toast('Conexión restablecida'));
setInterval(async()=>{if(!S.user||document.hidden)return;try{if(S.view==='social'){await loadSocial();render()}else if(S.view==='baskets'||S.view==='basket'){await refresh()}}catch{}},27000);
start().catch(err=>{$('#main').innerHTML=empty('⚠️','No se pudo iniciar SHOPPER',E(err.message),'<button class="btn primary" onclick="location.reload()">Reintentar</button>')});
